text:
{
  "units": [
    {
      "issue": "在追加交付归入同一借贷关系的明示限定前提下，识别银行贷款转贷的效力及实际取得财产的返还范围",
      "decisive_facts": [
        {
          "id": "f1",
          "fact": "银行贷款及借条形成于2022年8月24日，本案于2023年5月6日立案。",
          "source_role": "法院记载的程序事实及查明事实",
          "support": ["p-006", "p-012", "p-013", "p-014", "p-015"]
        },
        {
          "id": "f2",
          "fact": "三家银行向原告发放贷款合计544000.00元；原告陈述其将贷款扣除预扣款后转交被告。银行放款事实与资金转贷来源陈述应分层记录。",
          "source_role": "银行放款为法院查明事实；转贷来源包含原告陈述",
          "support": ["p-007", "p-012", "p-013", "p-014", "p-016"]
        },
        {
          "id": "f3",
          "fact": "借条、收条均记载544000.00元，但法院查明2022年8月24日至25日实际转账合计502000.00元。原告自述差额42000.00元为预扣的一年利息。",
          "source_role": "凭证内容及转账金额为法院查明事实；扣款性质为原告自述",
          "support": ["p-015", "p-016"]
        },
        {
          "id": "f4",
          "fact": "2022年12月，原告另向被告支付750.00元、1350.00元及20000.00元，合计22100.00元；付款方向仍为原告向被告。",
          "source_role": "法院查明事实",
          "support": ["p-017"]
        },
        {
          "id": "f5",
          "fact": "将上述22100.00元视为退还预扣款、归入同一借贷关系，是材料明示的分析限定，不是法院已经认定其法律归属，也不证明这笔款项独立来源于银行贷款。",
          "source_role": "原告主张及材料附加限定",
          "support": ["p-007", "scope-tail"]
        },
        {
          "id": "f6",
          "fact": "原告变更后的请求保留544000.00元本金及相关诉讼费用，不再列入原先的利息、逾期违约金请求。",
          "source_role": "诉讼请求记载",
          "support": ["p-007"]
        },
        {
          "id": "f7",
          "fact": "原告对银行的三笔贷款均已结清；这些记载不等于被告已向原告清偿。实际利息收付没有原始流水，材料明确不要求判定真实利息。",
          "source_role": "法院查明事实及材料范围说明",
          "support": ["p-012", "p-013", "p-014", "scope-tail"]
        }
      ],
      "support_spans": [
        {
          "id": "p-006",
          "locator": "normalized_text[p-006]",
          "quote": "本院于2023年5月6日立案后"
        },
        {
          "id": "p-007",
          "locator": "normalized_text[p-007]",
          "excerpts": [
            "贷款审批到账后，原告于2022年8月24日至25日分批将本金扣除利息后的50.20万元转至被告工商银行（账户已脱敏）账户中",
            "2022年12月5日至9日，被告因资金紧张请求原告退还部分利息2.21万，原告通过支付宝转2.21万给被告，故被告累计支付原告利息2.19万。",
            "诉讼中，原告变更诉讼请求为：1.判令被告归还借款本金54.40万元；2.判令被告承担本案诉讼及执行过程中涉及的案件受理费、执行费等全部相关诉讼费用。"
          ]
        },
        {
          "id": "p-012",
          "locator": "normalized_text[p-012]",
          "quote": "当日，广发银行向原告发放贷款14.40万元，后原告于2023年2月9日结清该贷款。"
        },
        {
          "id": "p-013",
          "locator": "normalized_text[p-013]",
          "quote": "当日，江苏银行向原告发放贷款20万元，后原告于2023年2月13日结清该贷款。"
        },
        {
          "id": "p-014",
          "locator": "normalized_text[p-014]",
          "quote": "当日，上海农商银行向原告发放贷款20万元，现贷款已结清。"
        },
        {
          "id": "p-015",
          "locator": "normalized_text[p-015]",
          "excerpts": [
            "今皮某（杨X）向马某借款人民币544000.00/",
            "当日，被告向原告出具收条一份，载明收到原告54.40万元，用于资金周转，收款方式为转账。"
          ]
        },
        {
          "id": "p-016",
          "locator": "normalized_text[p-016]",
          "quote": "2022年8月24日至2022年8月25日，原告通过其名下账户信息已脱敏的账户向被告名下账户信息已脱敏的账户转账四笔，共计50.20万元。诉讼中，原告自述上述金额系扣除贷款54.40万元一年的利息4.20万元。"
        },
        {
          "id": "p-017",
          "locator": "normalized_text[p-017]",
          "excerpts": [
            "被告曾通过微信指导原告配合办理贷款审批手续",
            "被告通过微信向原告借款750元用于缴纳家中水电费",
            "当日又表示要借款1,350元还花呗",
            "被告表示取2万元",
            "上述款项，原告均通过支付宝于当日向被告打款，合计22,100元。"
          ]
        },
        {
          "id": "scope-tail",
          "locator": "normalized_text末尾以“范围：”起始的未编号段；此ID仅为本次引用别名",
          "quote": "范围：按原告关于追加交付用于退还预扣款的陈述这一限定前提，计算同一借贷关系的返还范围；该前提不代表独立银行来源追踪。实际利息收付无原始流水，不要求判定真实利息。"
        },
        {
          "id": "r31",
          "source_id": "lending-2020-12",
          "provision": "31",
          "quote": "本规定施行后，人民法院新受理的一审民间借贷纠纷案件，适用本规定。",
          "url": "https://cicc.court.gov.cn/html/1/380/385/12844.html"
        },
        {
          "id": "r13",
          "source_id": "lending-2020-12",
          "provision": "13",
          "quote": "具有下列情形之一的，人民法院应当认定民间借贷合同无效：\n　　（一）套取金融机构贷款转贷的；",
          "url": "https://cicc.court.gov.cn/html/1/380/385/12844.html"
        },
        {
          "id": "r157",
          "source_id": "civil-code-2020",
          "provision": "157",
          "quote": "民事法律行为无效、被撤销或者确定不发生效力后，行为人因该行为取得的财产，应当予以返还；不能返还或者没有必要返还的，应当折价补偿。",
          "url": "https://www.court.gov.cn/zixun/xiangqing/233181.html"
        },
        {
          "id": "r26",
          "source_id": "lending-2020-12",
          "provision": "26",
          "quote": "借据、收据、欠条等债权凭证载明的借款金额，一般认定为本金。预先在本金中扣除利息的，人民法院应当将实际出借的金额认定为本金。",
          "url": "https://cicc.court.gov.cn/html/1/380/385/12844.html"
        },
        {
          "id": "r1260",
          "source_id": "civil-code-2020",
          "provision": "1260",
          "quote": "本法自2021年1月1日起施行。",
          "url": "https://www.court.gov.cn/zixun/xiangqing/233181.html"
        }
      ],
      "dependencies": {
        "nodes": [
          {
            "id": "d1",
            "state": "按2022年交易及2023年受理时点，采用所给2020年12月修正的民间借贷解释及民法典；不沿用2015年条文的附加要件。",
            "depends_on": ["f1"],
            "support": ["r31", "r1260"]
          },
          {
            "id": "d2",
            "state": "依所载银行贷款转付事实认定构成套取金融机构贷款转贷时，进入合同无效的规则路径；该版本不另要求证明高利转贷或借款人事先知情。",
            "depends_on": ["d1", "f2"],
            "support": ["p-007", "p-012", "p-013", "p-014", "p-016", "p-017", "r13"],
            "boundary": "这是基于所给事实的规则适用状态，不是原判结论摘录；不得把全部来源陈述改写成法院已认定的事实。"
          },
          {
            "id": "d3",
            "state": "区分凭证记载与实际交付，初次实际取得金额为502000.00元，不能仅凭借条、收条计入未交付的42000.00元。",
            "depends_on": ["f3"],
            "support": ["p-015", "p-016", "r26"],
            "boundary": "第26条用于说明预扣款下的金额识别；无效后的返还请求仍以第157条为依据。"
          },
          {
            "id": "d4",
            "state": "后续22100.00元是原告向被告的追加交付；仅在明示归属前提下计入同一关系，不作为被告还款扣减，也不据此另行认定资金来自银行。",
            "depends_on": ["f4", "f5"],
            "support": ["p-017", "scope-tail"]
          },
          {
            "id": "d5",
            "state": "限定计算对象为同一关系下被告取得财产的返还范围，不加入已撤出的利息、违约金请求，不把原告结清银行贷款重复计入或作为被告清偿。",
            "depends_on": ["f6", "f7"],
            "support": ["p-007", "p-012", "p-013", "p-014", "scope-tail"]
          },
          {
            "id": "d6",
            "state": "在无效规则路径及明示归属前提下，取得财产的返还计算基数为初次交付与追加交付之和。",
            "depends_on": ["d2", "d3", "d4", "d5"],
            "support": ["r157", "p-016", "p-017", "scope-tail"],
            "amount_check": {
              "currency": "CNY",
              "expression": "502000.00 + 22100.00",
              "result": "524100.00",
              "meaning": "限定范围内的返还计算基数，非原判金额，亦非完整卷宗下经过所有清偿、抵销核验的最终净欠款"
            }
          }
        ],
        "material_interactions": [
          "银行贷款转贷的效力状态决定采用无效后财产返还路径，而非直接执行借条全部约定。",
          "实际交付与凭证金额的差异改变返还计算基数。",
          "追加交付的方向及归属前提决定22100.00元是否计入同一关系；取消该前提后不得直接沿用本单元金额。"
        ]
      },
      "answerability": {
        "status": "conditional",
        "unit_type": "限定前提下的规则适用与金额归属单元",
        "supported_scope": "可识别适用规范、合同效力的规则路径及同一关系下实际取得财产的限定计算基数。",
        "court_holding_available": false,
        "not_supported": [
          "原审法院实际采用的理由和判决金额",
          "完整卷宗下最终净欠款",
          "追加22100.00元的独立银行资金来源",
          "真实利息支付、抵扣及损失赔偿数额"
        ],
        "downstream_condition": "后续题面须保留追加交付归属限定，并明确这是基于所给材料的规则适用，不是要求复述未提供的原判。"
      }
    }
  ],
  "rejected_units": [
    {
      "issue": "提取或解释原审法院实际裁判结论",
      "reason": "材料明确不提供原判理由和主文；不得以规则适用结果替代真实裁判。",
      "disposition": "隔离，待补充原判对应段落"
    },
    {
      "issue": "认定被告真实支付利息并据此计算最终净返还额",
      "reason": "缺少实际利息收付原始流水，且原告陈述存在金额矛盾；材料范围明确排除此判断。",
      "support": ["p-007", "p-016", "scope-tail"]
    },
    {
      "issue": "将22100.00元独立认定为新借款，或认定其独立来源于银行贷款",
      "reason": "p-017的聊天内容包含再次借款表述，而p-007称退还预扣款。当前仅有同一关系归属限定，没有足以另建独立借贷状态及资金来源的证据。",
      "support": ["p-007", "p-017", "scope-tail"]
    },
    {
      "issue": "多债务清偿顺序、保证责任及保证期间",
      "reason": "没有被告向原告作出不足额清偿的事实，也没有保证合同或保证人事实。规则清单中的相关条文不能补造这些状态。"
    },
    {
      "issue": "精确计算利息、违约金、无效过错赔偿或诉讼执行费用",
      "reason": "超出限定计算范围，且缺少相应收付、损失、过错或费用核定依据。撤出相关请求不等于法院已作实体驳回。"
    }
  ],
  "limitations": [
    {
      "type": "材料完整性",
      "detail": "当前为原案节选，new_scenario=false；未将其改造为虚构情景。缺少裁判理由、主文及完整证据原件，只能保留条件化的规则适用单元。"
    },
    {
      "type": "金额矛盾",
      "detail": "p-007称预扣42000.00元、退还22100.00元后累计支付利息21900.00元；前两数相减为19900.00元，相差2000.00元。该矛盾保持未解决，不能修正为真实利息事实，也不能据此另行扣减返还基数。"
    },
    {
      "type": "事实归属",
      "detail": "p-017确认追加付款及聊天内容，并未明确认定其属于退还预扣款。该归属依赖材料末尾限定，不能提升为原审法院认定。"
    },
    {
      "type": "来源核验",
      "detail": "本次仅分析提供的文本及规范摘录，未独立访问官方页面、复核哈希或核对案件原文。所列官方链接是可核验入口，不表示已完成独立核验；案件来源尚缺公开原文链接及冻结原文哈希。"
    },
    {
      "type": "定位质量",
      "detail": "范围限定段没有原始span_id，已用明确标注的本次引用别名定位。规范定位同时使用UTF-16与Unicode码点，后续自动校验须分别处理。"
    },
    {
      "type": "阶段边界",
      "detail": "本输出仅为P1依赖图及可回答性分析，未生成题面、接收种子、执行盲答或确认实测难度，不构成已验收训练数据。"
    }
  ]
}
